package com.narudzbine.identity.infrastructure.web;
import static org.assertj.core.api.Assertions.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.Test;
class CsvRequestsTest {
 private CsvRequests.Parsed parse(String value){return CsvRequests.parse(value,new com.narudzbine.shared.api.UuidGenerator(java.time.Clock.systemUTC()));}
 private static String quote(String value){return "\""+value.replace("\"","\"\"")+"\"";}
 @Test void quotedUnicodeBomEscapesAndCrLfPreserveNormalizedText(){var p=parse("\ufeffname,sku,description,basePrice,activate\r\n\"Café\",ABC-1,\"First, line\r\nSecond \"\"line\"\"\",12.34,false\r\n");assertThat(p.rowCount()).isEqualTo(1);assertThat(p.errors()).isEmpty();var row=p.rows().getFirst();assertThat(row.product().description()).isEqualTo("First, line\nSecond \"line\"");assertThat(row.product().minimumQuantity()).isEqualTo(1);assertThat(row.product().unitId()).isNull();assertThat(row.basePrice().toPlainString()).isEqualTo("12.34");assertThat(p.requiresPrice()).isTrue();}
 @Test void malformedStructureAndForbiddenOrDuplicateHeadersFailAsFileErrors(){for(String value:List.of("","sku,name\n","sku,name\na,\"unfinished","sku,name\na,b\"c","sku,name\na,\"b\" trailing","sku,name\ra,b","sku,name\na,b\0","sku,sku,name\na,b,c","sku,name,stock\na,b,0","id,sku,name\na,b,c","SKU,name\na,b")){assertThatThrownBy(()->parse(value)).as(value.replace('\0','?')).isInstanceOf(AuthHttpFailure.class);}}
 @Test void exactRecordAndCellBoundsAndFinalNewlineAreEnforced(){StringBuilder file=new StringBuilder("sku,name\n");for(int i=0;i<1000;i++){file.append("S").append(i).append(",Name\n");}assertThat(parse(file.toString()).rowCount()).isEqualTo(1000);assertThatThrownBy(()->parse(file+"LAST,Name\n")).isInstanceOf(AuthHttpFailure.class);assertThatThrownBy(()->parse("sku,name,description\nx,name,"+"x".repeat(20001))).isInstanceOf(AuthHttpFailure.class);assertThat(parse("sku,name\nx,name").rowCount()).isEqualTo(1);var p=parse("sku,name\nx,name\n\ny,name\n");assertThat(p.rowCount()).isEqualTo(3);assertThat(p.errors()).anySatisfy(e->{assertThat(e.row()).isEqualTo(2);assertThat(e.code()).isEqualTo("COLUMN_COUNT");});}
 @Test void allRowsAndIndependentFieldErrorsAreRetainedWithoutInvalidProposals(){var p=parse("sku,name,minimumQuantity,basePrice,activate,tagIds\nBAD SPACE,,0,0,yes,not-json\nOTHER,Name,-1,12.345,TRUE,{}\n");assertThat(p.rows()).isEmpty();assertThat(p.errors()).extracting(e->e.row()).contains(1,2);assertThat(p.errors()).extracting(e->e.column()).contains("sku","name","minimumQuantity","basePrice","activate","tagIds");assertThat(p.errors().size()).isGreaterThanOrEqualTo(10);}
 @Test void duplicateSkuErrorsMarkEveryNormalizedDuplicateEvenAnOtherwiseInvalidRow(){var p=parse("sku,name\n abc-1 ,One\nABC-1,Two\nAbc-1,\n");assertThat(p.errors().stream().filter(e->e.code().equals("DUPLICATE_SKU")).map(e->e.row()).toList()).containsExactly(1,2,3);}
 @Test void generatedQuotedDescriptionsRoundTripWithoutFormulaEvaluation(){var random=new Random(4180);String alphabet="abc,\"\n\tćž=+-@";for(int n=0;n<200;n++){var text=new StringBuilder("start");for(int i=0;i<100;i++){text.append(alphabet.charAt(random.nextInt(alphabet.length())));}text.append("end");var p=parse("sku,name,description\nABC,=2+2,"+quote(text.toString())+"\n");assertThat(p.errors()).isEmpty();assertThat(p.rows().getFirst().product().description()).isEqualTo(text.toString());assertThat(p.rows().getFirst().product().name()).isEqualTo("=2+2");}}
 @Test void strictTagsAndScalarValuesNeverSilentlyConvert(){var p=parse("sku,name,tagIds,minimumQuantity,quantityStep,basePrice\na,Name,"+quote("[] []")+",1,1,12.34\nb,Name,[],1.0,1,12.34\nc,Name,[],1,1,"+quote("12,34")+"\n");assertThat(p.errors()).extracting(e->e.column()).contains("tagIds","minimumQuantity","basePrice");assertThat(p.rows()).isEmpty();}
 @Test void unicodeCodePointLimitsDifferFromCellUtf16Limit(){String emoji="😀".repeat(5000);assertThat(parse("sku,name,description\na,Name,"+emoji).rows().getFirst().product().description()).isEqualTo(emoji);var p=parse("sku,name,description\na,Name,"+emoji+"x");assertThat(p.errors()).anySatisfy(e->assertThat(e.column()).isEqualTo("description"));assertThat(p.rows()).isEmpty();}
}
